
local pr=[==[]==]
local whl=
(function(...)
local yxctc={45,50,168,112,68,147,201,45,235,91,87,85,2,6,63,24,132,59,102,145,36,21,12,200,81,188}
local mej=bit32 or bit
local wnns=mej.bxor
for vdmh=1,#yxctc do yxctc[vdmh]=wnns(yxctc[vdmh],(250*vdmh+198)%256) end
local qpne="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local tf={}
for gxnr=1,#qpne do tf[qpne:byte(gxnr)]=gxnr-1 end
local function cv(str)
  local R={} local acc,nb=0,0
  for vfh=1,#str do
    local v=tf[str:byte(vfh)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function aijpd(key,data)
  local S={} for izoq=0,255 do S[izoq]=izoq end
  local j=0
  for asj=0,255 do
    j=(j+S[asj]+key[(asj%#key)+1])%256
    S[asj],S[j]=S[j],S[asj]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(wnns(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=aijpd(yxctc,cv(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local xzzf=nf()
return function(big) return xzzf(big) end
end)(...)

return whl(pr)
